import { PlaneGeometry, MeshBasicNodeMaterial, Group, Mesh, Color, DoubleSide } from 'three/webgpu';
import { uv, mix, vec3, texture, uniform, step, clamp } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headline =
    items.find((i) => i.role === 'headline')?.text ?? 'Features 3';
  const headlineSize =
    items.find((i) => i.role === 'headline')?.typography?.fontSize ?? 39;

  const root = new Group();
  root.name = 'features-card-3-label';

  // --- Card label plane sized to atlas aspect (512x320 => 1.6) ---
  const aspect = 512 / 320;
  const planeHeight = 0.5;
  const planeWidth = planeHeight * aspect;

  const geo = new PlaneGeometry(planeWidth, planeHeight, 1, 1);

  const inkColor = vec3(new Color(colors.ink));
  const surfaceColor = vec3(new Color(colors.surface));
  const accentColor = vec3(new Color(colors.accent));

  const grainAmount = uniform(0.0);

  const vGrad = uv().y;
  let baseColor = mix(surfaceColor, inkColor, vGrad);

  // thin accent tab marker on left edge (<10% of frame area)
  const tabMask = step(uv().x, 0.06);
  baseColor = mix(baseColor, accentColor, tabMask.mul(0.9));

  const material = new MeshBasicNodeMaterial({ side: DoubleSide });
  material.colorNode = baseColor;
  material.transparent = true;
  material.opacity = 0;

  const plane = new Mesh(geo, material);
  plane.name = 'label-backdrop';
  root.add(plane);

  // Billboard toward camera every frame
  root.onBeforeRender = (renderer, scene, camera) => {
    root.quaternion.copy(camera.quaternion);
  };

  // --- Grain texture overlay (subtle, loaded async, non-blocking) ---
  let grainTex = null;
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        grainTex = tex;
        tex.wrapS = THREE.RepeatWrapping;
        tex.wrapT = THREE.RepeatWrapping;
        const grainSample = texture(tex, uv()).rgb;
        const withGrain = mix(
          baseColor,
          mix(baseColor, grainSample, 0.12),
          clamp(grainAmount, 0, 1)
        );
        material.colorNode = withGrain;
        material.needsUpdate = true;
        gsap.to(grainAmount, { value: 1, duration: 0.4, ease: 'power2.out' });
      })
      .catch(() => {});
  }

  // --- Text: "Features 3" ---
  const textNode = ctx.fontAtlas.createText(headline, {
    fontSize: headlineSize,
    color: colors.paper,
    align: 'center',
  });
  textNode.position.set(0, 0, 0.01);
  textNode.scale.setScalar(0.0072); // px-ish sizing to scene-unit fit for small card label
  root.add(textNode);

  // --- Entrance motion (weighted-settle, non-linear, <=0.9s) ---
  root.scale.setScalar(0.96);
  const tl = gsap.timeline();
  tl.to(material, { opacity: 1, duration: 0.5, ease: 'power2.out' });
  tl.to(
    root.scale,
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.45, ease: 'power3.out' },
    0
  );
  tl.to(
    root.scale,
    { x: 1, y: 1, z: 1, duration: 0.45, ease: 'power4.out' },
    0.45
  );

  // --- Cinematic primitives (none specified) ---
  const primitiveHandles = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    const fn = ctx.primitives[prim.name];
    if (fn) {
      const handle = fn(root, prim.params ?? {});
      primitiveHandles.push(handle);
    }
  }

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    for (const handle of primitiveHandles) {
      handle?.cleanup?.();
    }
    geo.dispose();
    material.dispose();
    if (grainTex) grainTex.dispose?.();
    if (textNode.userData?.cleanup) textNode.userData.cleanup();
    root.onBeforeRender = null;
  };

  return root;
}
